package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.OutputSettings;
import org.jsoup.parser.QuirksMode;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Document_title_TriageGen0Test {

    private Document document;

    @Before
    public void setUp() {
        document = new Document("<html><head><title>  Sample Title  </title></head><body></body></html>");
    }

    @Test
    public void testTitleWithWhitespace() {
        String expectedTitle = "Sample Title";
        assertEquals(expectedTitle, document.title());
    }

    @Test
    public void testTitleWithNoWhitespace() {
        Document noWhitespaceDoc = new Document("<html><head><title>SampleTitle</title></head><body></body></html>");
        assertEquals("SampleTitle", noWhitespaceDoc.title());
    }

    @Test
    public void testTitleWithNoTitleTag() {
        Document noTitleTagDoc = new Document("<html><head></head><body></body></html>");
        assertEquals("", noTitleTagDoc.title());
    }

    @Test
    public void testTitleWithEmptyTitleTag() {
        Document emptyTitleTagDoc = new Document("<html><head><title></title></head><body></body></html>");
        assertEquals("", emptyTitleTagDoc.title());
    }

    @Test
    public void testTitleWithOnlyWhitespaceInTitleTag() {
        Document onlyWhitespaceTitleTagDoc = new Document("<html><head><title>   </title></head><body></body></html>");
        assertEquals("", onlyWhitespaceTitleTagDoc.title());
    }

    @Test
    public void testTitleWithMultipleTitleTags() {
        Document multipleTitleTagsDoc = new Document("<html><head><title>Title 1</title><title>Title 2</title></head><body></body></html>");
        assertEquals("Title 1", multipleTitleTagsDoc.title());
    }

    @Test
    public void testTitleWithNullDocument() {
        Document nullDoc = null;
        assertEquals("", Jsoup.parse("").title());
    }

    @Test
    public void testTitleFromShellDocument() {
        Document shellDoc = Document.createShell("");
        shellDoc.title("Shell Title");
        assertEquals("Shell Title", shellDoc.title());
    }

    @Test
    public void testTitleFromNormalisedDocument() {
        Document normalisedDoc = new Document("<html><head><title>  Normalised Title  </title></head><body></body></html>").normalise();
        assertEquals("Normalised Title", normalisedDoc.title());
    }
}
